from typing import List

class SolutionRecursive:
    def knapSack(self, W: int, wt: List[int], val: List[int], n: int) -> int:
        def dfs(i: int, cap: int) -> int:
            if i == n:
                return 0
            best = dfs(i + 1, cap)
            if wt[i] <= cap:
                best = max(best, val[i] + dfs(i + 1, cap - wt[i]))
            return best

        return dfs(0, W)

