from typing import List

class Solution:
    def knapSack(self, W: int, wt: List[int], val: List[int], n: int) -> int:
        dp = [0] * (W + 1)
        for i in range(n):
            # Reverse capacity prevents reusing the same item.
            for cap in range(W, wt[i] - 1, -1):
                dp[cap] = max(dp[cap], val[i] + dp[cap - wt[i]])
        return dp[W]

